def solve(data):
    winners = []
    anonymous = []

    for position, event in enumerate(data['events']):
        if 'id' not in event:
            anonymous.append((position, event))
            continue

        revision = event.get('revision', 0)
        for index, (event_id, best_revision, best_position, _) in enumerate(winners):
            if event_id == event['id']:
                if revision >= best_revision:
                    winners[index] = (event_id, revision, position, event)
                break
        else:
            winners.append((event['id'], revision, position, event))

    selected = anonymous + [
        (position, event)
        for _, _, position, event in winners
    ]
    selected.sort(key=lambda item: item[0])

    balances = {}
    for _, event in selected:
        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f"{account}|{currency}"
        balances[key] = balances.get(key, 0) + amount(event, data['rounding'])

    return {'balances': balances}
